fn add(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64> {
    let base: u64 = 1_000_000_000;
    let mut r = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u64;
